<?php
namespace App\Http\Controllers\Admin;
use App\Actions\Debt\AdjustDebtAction; use App\Actions\Debt\RecordDebtPaymentAction; use App\Http\Controllers\Controller; use App\Http\Requests\DebtAdjustmentRequest; use App\Http\Requests\DebtPaymentRequest; use App\Models\Debt; use Illuminate\Http\JsonResponse;
class DebtController extends Controller { public function pay(Debt $debt, DebtPaymentRequest $request, RecordDebtPaymentAction $action): JsonResponse { $this->assertRoom($debt); return response()->json(['data'=>$action->execute($debt,(int)$request->validated('amount'),$request->validated('payment_method'),$request->validated('reference'))]); } public function adjust(Debt $debt, DebtAdjustmentRequest $request, AdjustDebtAction $action): JsonResponse { $this->assertRoom($debt); $data=$request->validated(); return response()->json(['data'=>$action->execute($debt,$data['type'],(int)$data['amount'],$data['reason'])]); } private function assertRoom(Debt $debt): void { abort_unless($debt->room_id===request()->attributes->get('room')->id,404); } }
